// Each group replays the cases the TypeScript was captured with (apps/api/testdata/tools/capture-writes-player.test.mjs, the cases
// generated by gen-writes-player-cases.py): every answer (status, headers, body) and the rows the steps left behind in
// the player, club, notification, account and contact-request tables, and the audit events and notifications they did
// not write. Go answers differently from the Route Handler only where a step says "goExpects" (the deviations log has each).

func TestProfileGolden(t *testing.T)       { writetest.Replay(t, "testdata", "profile", build) }
func TestPrivacyGolden(t *testing.T)       { writetest.Replay(t, "testdata", "privacy", build) }
func TestNotificationsGolden(t *testing.T) { writetest.Replay(t, "testdata", "notifications", build) }
func TestClubsGolden(t *testing.T)         { writetest.Replay(t, "testdata", "clubs", build) }

// Leave club ends the pending slot transfers the player is part of (#1018, task 2.12).
func TestLeaveTransfersGolden(t *testing.T) { writetest.Replay(t, "testdata", "leavetransfers", build) }
func TestContactGolden(t *testing.T)        { writetest.Replay(t, "testdata", "contact", build) }
